import jax
import jax.numpy as jnp
from jax import lax

def grad_f(fn, x):
    return jax.grad(lambda t: fn(t))(x)

xs = {
    'x80': jnp.float32(80.0),
    'xn80': jnp.float32(-80.0),
    'x20': jnp.float32(20.0),
    'xn20': jnp.float32(-20.0),
}

out = {}

# logistic
for k, x in xs.items():
    out[f'logistic_grad_{k}'] = grad_f(lambda t: lax.logistic(t), x)

# tanh
for k, x in xs.items():
    out[f'tanh_grad_{k}'] = grad_f(lambda t: lax.tanh(t), x)

# expm1
for k, x in xs.items():
    out[f'expm1_grad_{k}'] = grad_f(lambda t: lax.expm1(t), x)

for name, val in out.items():
    probe(name, val)

